const modalObserver=typeof MutationObserver!=='undefined'?new MutationObserver(()=>{const open=!!overlay.firstChild;app.inert=open;canvas.inert=open;}):null;modalObserver?.observe(overlay,{childList:true});
document.addEventListener('keydown',e=>{if(!overlay.firstChild||e.key!=='Tab')return;const nodes=[...overlay.querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]')].filter(el=>el.getClientRects().length);if(!nodes.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)challengeController?.pause?.();else challengeController?.resume?.();updateChallengeStatus();});
