window.AtlasGame={get state(){return save;},get active(){return active;},get grid(){return grid;},get selectedDestination(){return routeSelected;},get routeEdges(){return edges.map(edge=>edge.slice());},startTutorial,gameOver,retryChallenge,enterCampus,findPath,walkable,landmarkFor,shortestRoute,routeOptions,travelTo,nextEncounter,atlas,renderHUD,research,completeEncounter,encounters};
